<?php
 namespace ehr; interface iPatientResource extends iResource { } class PatientResource extends Resource implements iPatientResource { protected $patientGUID; public function __construct(PatientLink $link, string $aName, string $aTableName, $aSource) { parent::__construct($link, $aName, $aTableName, $aSource); $this->fieldPatientGUID = null; } public function getPatientGUID(): ?string { return $this->patientGUID; } public function setPatientGUID(string $guid): void { $this->patientGUID = $guid; } public function getItem(): ?PatientResourceItem { return $this->basicItem; } public function setItem(PatientResourceItem $item): void { $this->basicItem = $item; } public function getLink(): ?PatientLink { return $this->basicLink; } public function setLink(PatientLink $link): void { $this->basicLink = $link; } public function getFieldPatientGIUD(): ?string { return $this->fieldPatientGUID; } public function setFieldPatientGUID(string $field): void { $this->fieldPatientGUID = $field; } public function createResourceItem(): void { $this->basicItem = new PatientResourceItem($this); } public function afterOpenBeforeSend(): void { } public function getItemFromDB(int $key): string { if (empty($this->getFieldPatientGIUD())) { return selectSqlValue($this->getLink()->getConnetDb(), "select codeHL7 from medPatient where medPatientCode = {$key}"); } return $this->getFieldPatientGIUD(); } private function makeMessagePatientInfo(PatientResourceItem $item, bool $guid = true, bool $key = true): string { return "а/к {$item->getNumberHistory()}" . ($key ? ", key: {$item->getId()}" : '') . ($guid ? ($item->getGUID() ? ", GUID: {$item->getGUID()}" : '') : ''); } public function sendItem2DPC(int $key): ?string { parent::sendItem2DPC($key); $item = $this->getItem(); if ($item->getState() === 1 || empty($item->getGUID())) { if (empty($item->getGUID())) { $this->addNewPatient($item); } else { $link = $this->getLink(); $exchange = $link->getExchange(); $logger = $link->getLogger(); $this->json = $exchange->getJSONResult( $exchange->rfc("{$link->getLs()->getParam('urlDPC')}Patient/{$item->getGUID()}"), "при поиске в ЦОД пациента, {$this->makeMessagePatientInfo($item, true, false)}", false ); if ($link->getAnswerCode() === 404) { $logger->addLog( "! попытка повторной регистрации в ЦОД пациента, {$this->makeMessagePatientInfo($item)}" ); $item->clearGUIDs(); $item->initJSONbase(); $this->addNewPatient($item); $logger->addLog( "! повторно зарегистрирован в ЦОД пациента, {$this->makeMessagePatientInfo($item)}" ); } else { if (!$exchange->validResult($link->getAnswerCode())) { return null; } $item->setVersionGUID(LinkJSON::getNodeValueByPath($this->json, LinkJSON::SOURCE_VERSION_ID)); if (empty($item->getVersionGUID())) { $logger->addLog( "ошибка получения в ЦОД GUID версии пациента, {$this->makeMessagePatientInfo($item)}", '', Logger::LMT_ERROR, true ); } else { $prevBarcode = LinkJSON::getPatientBarcode($this->json); if ($prevBarcode === $item->getBarcode()) { if (!$item->getIsLocal()) { $org_ref = LinkJSON::getNodeValueByPath($this->json, LinkJSON::SOURCE_ORG_REF); if (!empty($org_ref)) { $item->setEnterpriseGUID(Resource::deletePrefix($org_ref, self::RES_MO_PREFIX)); } $item->appendJSON(); $this->updatePatientAll($item); } } else { $logger->addLog( "в ЦОД обнаружен неактивный НИКМО {$prevBarcode} у пациента, {$this->makeMessagePatientInfo($item)}" ); $item->clearGUIDs(); $item->initJSONbase(); $this->addNewPatient($item); $logger->addLog( " пациент заново добавлен в ЦОД с НИКМО {$item->getBarcode()}, {$this->makeMessagePatientInfo($item)}" ); } } } } $this->deActivatePatientByPIN(); } return $item->getGUID(); } private function addNewPatient(PatientResourceItem &$item): void { $link = $this->getLink(); $exchange = $link->getExchange(); $ls = $link->getLs(); $urlDPC = $ls->getParam('urlDPC'); $this->json = $exchange->getJSONResult( $exchange->rfc("{$urlDPC}Patient?identifier=" . LinkSetup::ID_URL_BASNET . "/patient-medication-card|{$item->getBarcode()}&_format=json" ), "при поиске в ЦОД пациента, {$this->makeMessagePatientInfo($item, false)}, ШК {$item->getBarcode()}", true); $resource = LinkJSON::foundResource($this->json, $this->getName()); if (!$this->checkAndUpdatePatientItem($item, $resource)) { $logger = $link->getLogger(); if (!empty($item->getPIN())) { $exchange->rfc("{$urlDPC}Patient?identifier=" . LinkSetup::ID_URL_BASNET . "/patient-personal-passport-number|{$item->getPIN()}&_format=json"); if ($exchange->validResult($link->getAnswerCode())) { $this->checkAndUpdatePatientItem($item, $resource); } else { if ($link->getAnswerCode() !== 404) { $logger->addLog( "ошибка {$link->getAnswerCode()} при поиске в ЦОД пациента, {$this->makeMessagePatientInfo($item, false)}, PIN {$item->getPIN()}", '', Logger::LMT_ERROR, true ); } } } $item->appendJSON(); $this->json = $exchange->getJSONResult( $exchange->rfc("{$urlDPC}Patient", Exchange::HTTP_POST, $item->getJSONData()), "при регистрации в ЦОД пациента, {$this->makeMessagePatientInfo($item, false)}", true); $item->setGUID(LinkJSON::getNodeValueByPath($resource, 'id')); if (empty($item->getGUID())) { $logger->addLog( "ошибка получения GUID регистрации в ЦОД пациента, {$this->makeMessagePatientInfo($item, false)}", '', Logger::LMT_ERROR, true ); } else { $this->dbUpdatePatient($item); } } } private function checkAndUpdatePatientItem(PatientResourceItem &$item, \stdClass $resource): bool { $id = LinkJSON::getNodeValueByPath($resource, 'id'); $versionId = LinkJSON::getNodeValueByPath($resource, LinkJSON::SOURCE_VERSION_ID); if (empty($id) && empty($versionId)) { return false; } $item->setGUID($id); $item->setVersionGUID($versionId); $this->checkManagingOrganizationAndUpdate($item, $resource); return true; } private function checkManagingOrganizationAndUpdate(PatientResourceItem &$item, \stdClass $resource): void { if ($item->getIsLocal() || empty(LinkJSON::getNodeValueByPath($resource, LinkJSON::SOURCE_ORG_REF))) { return; } $item->setEnterpriseGUID( self::deletePrefix(LinkJSON::getNodeValueByPath($resource, LinkJSON::SOURCE_ORG_REF), self::RES_MO_PREFIX) ); $item->appendJSON(); $this->updatePatientAll($item); } private function updatePatientAll(PatientResourceItem $item): void { $this->dpcUpdatePatient($item); $this->dbUpdatePatient($item); } private function dpcUpdatePatient(PatientResourceItem $item): void { $link = $this->getLink(); $exchange = $link->getExchange(); $this->json = $exchange->getJSONResult( $exchange->rfc( "{$link->getLs()->getParam('urlDPC')}Patient/{$item->getGUID()}", Exchange::HTTP_PUT, $item->getJSONData() ), "при обновлении в ЦОД пациента, {$this->makeMessagePatientInfo($item)}", true ); } private function dbUpdatePatient(PatientResourceItem $item): void { $db = $this->getLink()->getConnetDb(); executeSql($db, <<<"EOT"
update medPatient set
       codeHL7 = '{$item->getGUID()}',
       state = null
where medPatientCode = {$item->getId()}
EOT
); $item->setState(0 ); if ($item->getBarState() === 0) { executeSql($db, <<<"EOT"
update madBarCode set
       state = 1
where barCode = '{$item->getBarcode()}'
  and state = 0
EOT
); $item->setState(1); } } public function deActivatePatientByPIN(): void { $item = $this->getItem(); $link = $this->getLink(); $ls = $link->getLs(); $exchange = $link->getExchange(); if (empty($item->getPIN()) || $item->getGUID()) { return; } $urlPDC = $ls->getParam('urlDPC'); $pin = $item->getPIN(); $url = "{$urlPDC}Patient?identifier=" . LinkSetup::ID_URL_BASNET . "/patient-personal-passport-number|{$pin}&_format=json"; $this->json = $exchange->getJSONResult( $exchange->rfc($url), "при поиске в ЦОД списка пациентов по PIN {$pin} ({$this->makeMessagePatientInfo($item, false)})", true ); $rPatient = LinkJSON::foundResource($this->json, $this->getName()); if (empty($rPatient)) { return; } $id = LinkJSON::getNodeAttributeValue($rPatient, 'id'); if (empty($id) || $id === $item->getId()) { return; } if (LinkJSON::getNodeAttributeValue($rPatient, 'active') == true) { LinkJSON::setNodeValue($rPatient, 'active', false); $this->json = $exchange->getJSONResult( $exchange->rfc("{$urlPDC}Patient/{$id}", Exchange::HTTP_PUT, $this->json), "при попытке деактивациив ЦОД пациента с GUID {$id}", true ); } } } 